export type MetricRow = {
  readonly cell: string;
  readonly shock: string | null;
  readonly clock: string | null;
  readonly books: number | null;
  /** the arm A is compared against on this row */
  readonly arm: "H1" | "H2" | "H3" | "P";
  readonly armWhat: string;
  readonly survivalA: number;
  readonly survivalX: number;
  /** book-survival advantage of A over that arm, in positions kept per hundred */
  readonly advantagePp: number;
  /** the study's 95% interval on that advantage — a cluster bootstrap over paths */
  readonly advantageLoPp: number | null;
  readonly advantageHiPp: number | null;
  /** true when the advantage is not distinguishable from zero at this sample size */
  readonly advantageSpansZero: boolean | null;
  /** true when the two arms did the same thing on every path, which is not the same statement */
  readonly advantageDegenerate: boolean | null;
  /** median paired gap in terminal equity, A − that arm, in bps of opening equity */
  readonly gapBps: number;
  /** whether this row is drawn in the figure or only listed in the table */
  readonly plotted: boolean;
  readonly kind: "cell" | "pooled";
};

