// --- work versus night ------------------------------------------------------

export type ClockRow = {
  readonly arm: "A" | "H1" | "H2" | "H3" | "P";
  readonly label: string;
  readonly clock: "work" | "night";
  /** book-level survival: the fraction of POSITIONS kept, book-count weighted */
  readonly survival: number;
  /** how many book-level ledgers that fraction is over */
  readonly nBooks: number;
  /** how many independent price paths those ledgers came from */
  readonly nPaths: number;
  /** the 95% Wilson interval the figure draws, after the clustering adjustment */
  readonly loPct: number;
  readonly hiPct: number;
  /** the same interval before it — what 800 book ledgers would give if they were 800 independent draws */
  readonly loPlainPct: number;
  readonly hiPlainPct: number;
  /** 1 + (mean books per path − 1) × ICC: how much of the raw n the clustering costs */
  readonly designEffect: number;
  /** the same fraction inside each shock, in the study's own shock order */
  readonly byShock: readonly { readonly shock: string; readonly survival: number }[];
  /** night minus work, in positions kept per hundred; null on the work row */
  readonly changePp: number | null;
  /** the interval on that CHANGE — a cluster bootstrap over paths, not the two rate intervals subtracted */
  readonly changeLoPp: number | null;
  readonly changeHiPp: number | null;
  /** true when the change is not distinguishable from zero, which for three of the five arms it is not */
  readonly changeSpansZero: boolean | null;
};

